#Requires -Version 5.1
# fix-rrhh-disponibilidad-definitivo.ps1
# 
# CAUSA EXACTA DEL PROBLEMA (3 bugs independientes):
#
# BUG 1 — obrasPanelItems: dateStrs NO estaba en las dependencias del useMemo.
#   La variable primeraFecha = dateStrs[0] se calculaba dentro del memo pero
#   al cambiar de semana (navegar a sem 6-12 jul) dateStrs cambiaba sin que
#   el memo se recalculara. Bikerlan 1 seguia apareciendo en el panel lateral.
#   FIX: dateStrs añadido a las deps. El panel ahora recalcula al cambiar semana.
#
# BUG 2 — displayGrid fila SIN ASIGNAR: usaba rrhh.filter(asignable !== false)
#   sin comprobar fecha_inicio/fecha_fin. Bikerlan 1 aparecia en la fila
#   amarilla SIN ASIGNAR de TODAS las semanas, no solo las de su periodo.
#   FIX: se llama a checkRrhhDisponibilidad(person, ds) por cada dia concreto.
#   Solo aparece en SIN ASIGNAR si está disponible ese dia especifico.
#
# BUG 3 — Filtro de panel por dia unico: el panel filtraba por primeraFecha
#   (lunes de la semana). Si Bikerlan empieza el mie 14, el lunes 13 daba
#   false y Bikerlan no aparecia ni el mie-vie. Ahora filtra por "disponible
#   en ALGUN dia de la semana" y el drag-drop bloquea el dia incorrecto.
#
# MENSAJES DE ERROR MEJORADOS:
#   "Bikerlan 1 no esta disponible el 06/07/2026.
#    Su periodo de disponibilidad es del 14/07/2026 al 24/07/2026."

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Fix disponibilidad RRHH definitivo" -ForegroundColor Cyan

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\planificacion\page.tsx"), $bytes)

$c = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\planificacion\page.tsx"), [System.Text.Encoding]::UTF8)
$ok1 = $c.Contains("resourceSearch, dateStrs]")
$ok2 = $c.Contains("rrhhDisponiblesSemana")
$ok3 = $c.Contains("checkRrhhDisponibilidad(person, ds)")
$ok4 = $c.Contains("Su periodo de disponibilidad")
if ($ok1) { Write-Host "  OK: dateStrs en deps de obrasPanelItems" -ForegroundColor Green } else { Write-Host "  ERROR BUG1" -ForegroundColor Red }
if ($ok2) { Write-Host "  OK: filtro por semana en panel lateral" -ForegroundColor Green } else { Write-Host "  ERROR BUG1b" -ForegroundColor Red }
if ($ok3) { Write-Host "  OK: SIN ASIGNAR filtra por fecha del dia" -ForegroundColor Green } else { Write-Host "  ERROR BUG2" -ForegroundColor Red }
if ($ok4) { Write-Host "  OK: mensaje de error con periodo completo" -ForegroundColor Green } else { Write-Host "  ERROR BUG3" -ForegroundColor Red }

Write-Host ""
Write-Host '  git add "src\app\planificacion\page.tsx"'
Write-Host '  git commit -m "fix: disponibilidad RRHH - dateStrs deps + SIN ASIGNAR por dia + mensajes"'
Write-Host '  git push'
